        return None
    if choice == 'request_only':
        return ['request_by', ['disclosing_party']]
    if choice == 'agreement_termination_only':
        return ['agreement_termination']
    if choice == 'relationship_termination_only':
        return ['relationship_termination']
    if choice == 'project_termination_only':
